from django.utils.html import strip_tags


# Categories from the article editor design; a site that already has its own keeps them.
DEFAULT_CATEGORIES = (
    ("Аналитика", "analytics"),
    ("Стратегии", "strategies"),
    ("Обзоры матчей", "match-reviews"),
    ("Букмекеры", "bookmakers"),
    ("Новичкам", "beginners"),
)


def add_default_categories(apps, schema_editor):
    ArticleCategory = apps.get_model("front", "ArticleCategory")
    if ArticleCategory.objects.exists():
        return
    for order, (name, slug) in enumerate(DEFAULT_CATEGORIES, start=1):
        ArticleCategory.objects.create(name=name, slug=slug, sort_order=order * 10)


def fill_reading_time(apps, schema_editor):
    CapperArticle = apps.get_model("cabinet", "CapperArticle")
    for article in CapperArticle.objects.only("pk", "content"):
        words = len(strip_tags(article.content).split())
        CapperArticle.objects.filter(pk=article.pk).update(reading_time_minutes=max(1, (words + 199) // 200))



